/**
 * Sprite sheet catalogue.
 *
 * Frame sizes are in world pixels (one map tile is 70). The images are rendered at `SPRITE_RES`
 * times that size and packed row-major into a grid no wider than `MAX_SHEET_PX`, so frame `i` is
 * at column `i % columns`, row `floor(i / columns)`. The engine only needs frame counts and sizes
 * (for directions, animation and hit offsets); the render layer maps each id to the bundled image
 * (see `src/render/assets.ts`). The art is generated by `tools/sprites`.
 */

/** Image pixels per world pixel in every sprite sheet and map background. */
export const SPRITE_RES = 2;
/** Widest sprite sheet image, in pixels (keep in sync with `tools/sprites/build.py`). */
const MAX_SHEET_PX = 2048;

export interface SpriteSheet {
  frameWidth: number;
  frameHeight: number;
  frames: number;
  /** Frames per row in the image. */
  columns: number;
}

const strip = (frameWidth: number, frameHeight: number, frames: number): SpriteSheet => ({
  frameWidth,
  frameHeight,
  frames,
  columns: Math.max(1, Math.min(frames, Math.floor(MAX_SHEET_PX / (frameWidth * SPRITE_RES)))),
});

/** Source rectangle of a frame in the sheet image, in image pixels. */
export function frameRect(sheet: SpriteSheet, frame: number) {
  const col = frame % sheet.columns;
  const row = Math.floor(frame / sheet.columns);
  return {
    x: col * sheet.frameWidth * SPRITE_RES,
    y: row * sheet.frameHeight * SPRITE_RES,
    width: sheet.frameWidth * SPRITE_RES,
    height: sheet.frameHeight * SPRITE_RES,
  };
}

/** Square frames. */
const squares = (size: number, frames: number) => strip(size, size, frames);

